import attr
import pytest
from attr import FrozenInstanceError

@attr.s(frozen=True)
class MyException(Exception):
    msg = attr.ib()

def test_frozen_exception_mutation():
    e = MyException("test")
    # This should be allowed
    try:
        e.__suppress_context__ = True
        print("Successfully set __suppress_context__")
    except FrozenInstanceError:
        print("Failed to set __suppress_context__")
    except Exception as ex:
        print(f"Unexpected exception: {type(ex).__name__}: {ex}")

    # __notes__ might not exist on all Python versions but should be allowed if it does
    try:
        e.__notes__ = "some note"
        print("Successfully set __notes__")
    except FrozenInstanceError:
        print("Failed to set __notes__")
    except Exception as ex:
        print(f"Unexpected exception: {type(ex).__name__}: {ex}")

if __name__ == \"__main__\":
    test_frozen_exception_mutation()
'

